AssistantMessageToolRequest(name='create', tool_call_id='tooluse_1I7Vg1LzxvUE9XyPAmAS5K', arguments={'file_text': "/* Reset and base styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: #f8f9fa;
    color: #1a1a1a;
    line-height: 1.6;
}

header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 2rem;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

header h1 {
    font-size: 2rem;
    font-weight: 600;
}

main {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.image-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 2rem;
}

.image-card {
    background: white;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.image-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
}

.image-card img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    display: block;
}

.card-content {
    padding: 1.5rem;
}

.card-content h2 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
    color: #1a1a1a;
}

.card-content p {
    color: #666;
    font-size: 0.95rem;
    margin-bottom: 1rem;
}

/* Button styles */
button {
    font-family: inherit;
    cursor: pointer;
}

.delete-btn {
    width: 100%;
    padding: 0.75rem 1rem;
    background-color: #ef4444;
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    transition: background-color 0.2s ease, transform 0.1s ease;
}

.delete-btn:hover {
    background-color: #dc2626;
}

.delete-btn:active {
    transform: scale(0.98);
}

.delete-btn:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

/* Dialog styles */
dialog {
    border: none;
    border-radius: 16px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
    padding: 2rem;
    max-width: 420px;
    width: 90%;
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
}

dialog h2 {
    margin-bottom: 1rem;
    font-size: 1.5rem;
    color: #1a1a1a;
}

dialog p {
    color: #666;
    margin-bottom: 1.5rem;
    line-height: 1.5;
}

.dialog-actions {
    display: flex;
    gap: 1rem;
    justify-content: flex-end;
}

.btn {
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 500;
    transition: background-color 0.2s ease, transform 0.1s ease;
    cursor: pointer;
}

.btn:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

.btn:active {
    transform: scale(0.98);
}

.btn-secondary {
    background-color: #e5e7eb;
    color: #1a1a1a;
}

.btn-secondary:hover {
    background-color: #d1d5db;
}

.btn-danger {
    background-color: #ef4444;
    color: white;
}

.btn-danger:hover {
    background-color: #dc2626;
}

/* Accessibility - ensure high contrast for forced colors mode */
@media (forced-colors: active) {
    dialog {
        border: 2px solid CanvasText;
    }

    .btn {
        border: 1px solid ButtonBorder;
    }

    .delete-btn {
        border: 1px solid ButtonBorder;
    }
}

/* Responsive design */
@media (max-width: 768px) {
    header h1 {
        font-size: 1.5rem;
    }

    .image-grid {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }

    dialog {
        width: 95%;
        padding: 1.5rem;
    }

    .dialog-actions {
        flex-direction: column;
    }

    .btn {
        width: 100%;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}
