 const dialog = document.getElementById('delete-dialog');
 const deleteButtons = document.querySelectorAll('.delete-btn');
 const cancelButton = dialog.querySelector('[data-close]');
 const confirmButton = dialog.querySelector('[data-confirm]');

 let currentImageCard = null;

 deleteButtons.forEach(button => {
     button.addEventListener('click', (e) => {
         currentImageCard = e.target.closest('.image-card');
         dialog.showModal();
     });
 });

 cancelButton.addEventListener('click', () => {
     dialog.close('cancel');
 });

 confirmButton.addEventListener('click', () => {
     dialog.close('delete');
 });

 dialog.addEventListener('close', () => {
     if (dialog.returnValue === 'delete' && currentImageCard) {
         currentImageCard.style.animation = 'fadeOut 0.3s ease forwards';
         setTimeout(() => {
             currentImageCard.remove();
             currentImageCard = null;
         }, 300);
     }
     currentImageCard = null;
 });

 dialog.addEventListener('keydown', (e) => {
     if (e.key === 'Escape') {
         dialog.close('cancel');
     }
 });

 const style = document.createElement('style');
 style.textContent = `
     @keyframes fadeOut {
         from {
             opacity: 1;
             transform: translateY(0);
         }
         to {
             opacity: 0;
             transform: translateY(10px);
         }
     }
 `;
 document.head.appendChild(style);

